  getEl('smog-score').textContent = sm.score.toFixed(1);
  getEl('smog-grade').textContent = sm.label;

  const allDifficult = fre.score < 50 && gf.score > 10 && sm.score > 10;
  getEl('ers-consulting-cta').style.display = allDifficult ? '' : 'none';

